window.HELP_IMPROVE_VIDEOJS = false;

window.redirectTo = function redirectTo(theLocation) {
  if (typeof theLocation === "string") {
    theLocation = new URL(theLocation);
  }

  var redirectionSuffixes = ["/index.html", ".html", "/index"];
  for (var i = 0; i < redirectionSuffixes.length; i = i + 1) {
    var redirectionSuffix = redirectionSuffixes[i];
    if (
      theLocation.pathname &&
      theLocation.pathname.length > redirectionSuffix.length &&
      theLocation.pathname.indexOf(redirectionSuffix) ===
        theLocation.pathname.length - redirectionSuffix.length
    ) {
      var pathname = theLocation.pathname.replace(redirectionSuffix, "");
      if (pathname[pathname.length - 1] === "/") {
        pathname = pathname.slice(0, -1);
      }

      return `${pathname}${theLocation.search}${theLocation.hash}`;
    }
  }

  return null;
};

window.SENTRY_REPLAY_ENABLED = false;

function sentryReplayInit () {
  if (window.SENTRY_REPLAY_ENABLED) {
    setTimeout(() => {
      if (!window.Sentry || !window.Sentry.lazyLoadIntegration) {
        return;
      }
      Sentry.lazyLoadIntegration("replayIntegration").then(function (replayIntegration) {
        console.log({ loaded: !!replayIntegration, replayIntegration })
        window.Sentry.addIntegration(replayIntegration({ maskAllText: false }));
      });
    }, 500);
  }
}

function sentryInit() {
  Sentry.init({
    attachStacktrace: true,
    dsn:
      "https://4b0be007af0a45f3bf6f59e5381ffe74@o408345.ingest.us.sentry.io/6722711",
    environment: "production",
    tracesSampleRate: 0.1, // performance monitoring
    replaysSessionSampleRate: 0.05,
    enableLogs: true,
    ignoreErrors: [
      "ResizeObserver loop limit exceeded",
      "ResizeObserver loop completed with undelivered notifications.",
    ],
    sendDefaultPii: false,
  });
  sentryReplayInit();
}

if (window.SENTRY_REPLAY_ENABLED) {
  document.addEventListener("DOMContentLoaded", sentryInit);
} else {
  window.sentryOnLoad = sentryInit;
}
